    V_ref = sol["Terminal voltage [V]"].entries
    t_ref = sol["Time [s]"].entries # Convert to hours

    param = pybamm.ParameterValues("Chen2020")
    param["Current function [A]"] = current_interpolant
    param["Positive electrode diffusivity [m2.s-1]"] *= 100.
    param["Negative electrode diffusivity [m2.s-1]"] *= 20.
    param["Negative electrode active material volume fraction"] *= 0.7
    PBM_model = pybamm.lithium_ion.SPM()
    sim = pybamm.Simulation(PBM_model, parameter_values=param)
    sol = sim.solve(initial_soc=0.9, t_eval=t_eval)

    V = sol["Terminal voltage [V]"].entries
    t = sol["Time [s]"].entries  # Convert to hours

